window.kbPageData["views/entry/k-b2e53bff22725361"] = {"key":"entry/k-b2e53bff22725361","state":{"route":"entry/k-b2e53bff22725361"},"node":{"id":"k-b2e53bff22725361","mode":"k","title":"等边三角形的内切圆半径","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["等边三角形的内切圆半径等于高的三分之一"],"qs":["江苏 2024 C类 行测#65"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"等边三角形的内切圆半径等于其高的三分之一。其内心与重心重合，重心到一边中点的距离等于对应中线长度的三分之一。","review":{"definition":"等边三角形的内切圆半径等于其高的三分之一。其内心与重心重合，重心到一边中点的距离等于对应中线长度的三分之一。","explanation":"本题正六边形的外接圆半径等于边长 2，因而三角形 ACE 的外接圆半径 AO 为 2。设 H 为 CE 的中点，则 AH 既是中线也是高。重心 O 将 AH 分成 AO 和 OH 两段，AO＝2OH，所以 OH＝1，即内切圆半径。","references":[],"evidence":"所求圆半径OH=AH-AO","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#65":{"paper":"江苏 2024 C类 行测","n":65,"mod":"数量关系","src":["3f1ec77ae8a18519b57e.pdf",11],"asrc":["02d6b49839583bdaf297.pdf",18],"card":"56ff358139b5a56940b95a72","links":[{"id":"k-b2e53bff22725361","role":"解题依据","why":"内心将高分成顶点侧和底边侧两段，底边侧占全高的三分之一，可据此确定半径。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-b2e53bff22725361":[["江苏 2024 C类 行测#65"]]}};
